const allItems = items;

if (!allItems || allItems.length === 0) {
  return [];
}

const names = allItems
  .filter(item => item.json && item.json.Name)
  .map(item => item.json.Name);

return [{
  json: {
    names: names
  }
}];

// Код для ноды Code в n8n
// Случайным образом выбирает 5 элементов и объединяет их в один объект

// Получаем все входные items
const allItems = items;

// Проверяем, что есть элементы для обработки
if (!allItems || allItems.length === 0) {
  return [];
}

// Определяем количество элементов для обработки (максимум 5)
const itemsToProcess = allItems.length <= 5 ? allItems : (() => {
  // Создаем копию массива для перемешивания
  const shuffled = [...allItems];

  // Алгоритм Fisher-Yates для случайного перемешивания
  for (let i = shuffled.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
  }

  // Возвращаем первые 5 элементов
  return shuffled.slice(0, 5);
})();

// Объединяем все items в один объект с префиксами
const mergedJson = {};

itemsToProcess.forEach((item, index) => {
  const prefix = `CQ_${index + 1}_`;

  // Добавляем префикс к каждому ключу и объединяем в один объект
  Object.keys(item.json).forEach(key => {
    mergedJson[prefix + key] = item.json[key];
  });
});

// Возвращаем один item со всеми полями
return [{
  json: mergedJson
}];

