  });
});

// Возвращаем один item со всеми полями
return [{
  json: mergedJson
}];

// Код для ноды Code в n8n
// Преобразует ответы формы в отдельные объекты с Question и User_ans

// Получаем все входные items
const allItems = items;

// Проверяем, что есть элементы для обработки
if (!allItems || allItems.length === 0) {
  return [];
}

// Список служебных полей, которые нужно исключить
const systemFields = ['submittedAt', 'formMode'];

// Результирующий массив объектов
const result = [];

// Обрабатываем каждый item
allItems.forEach((item) => {
  // Проходим по всем ключам объекта
  Object.keys(item.json).forEach(key => {
    // Пропускаем служебные поля
    if (systemFields.includes(key)) {
      return;
    }

    // Создаем объект для каждого вопроса-ответа
    result.push({
      json: {
        Question: key,
        User_ans: item.json[key]
      }
    });
  });
});

return result;

// Код для ноды Code в n8n
// Объединяет все items из Merge ноды в один item с массивом
// Сохраняет все данные без потерь

// Получаем все входные items из Merge ноды
const allItems = items;

// Проверяем, что есть элементы для обработки
if (!allItems || allItems.length === 0) {
  return [];
}

// Результирующий массив всех вопросов-ответов
const mergedArray = [];

// Обрабатываем каждый item
allItems.forEach((item) => {
  // Если item уже содержит массив объектов
  if (Array.isArray(item.json)) {
    item.json.forEach(obj => {
      // Если объект имеет поля Question и User_ans, используем их напрямую
      if (obj.Question && obj.User_ans !== undefined) {
        mergedArray.push({
          Вопрос: obj.Question,
          User_ans: obj.User_ans
        });
      }
      // Если объект имеет другие поля, сохраняем его полностью
      else {
        mergedArray.push(obj);
      }
    });
  } 
  // Если item содержит объект с полями Question и User_ans
  else if (item.json.Question && item.json.User_ans !== undefined) {
    mergedArray.push({
      Вопрос: item.json.Question,
      User_ans: item.json.User_ans
    });
  }
  // Если item содержит объект с полями Вопрос и User_ans (старый формат)
  else if (item.json.Вопрос && item.json.User_ans !== undefined) {
    mergedArray.push({
      Вопрос: item.json.Вопрос,
      User_ans: item.json.User_ans
    });
  }
  // Если item содержит объект с другими полями (например, результаты)
  else {
    // Сохраняем весь объект как есть
    mergedArray.push(item.json);
  }
});

// Возвращаем один item с массивом всех объектов
return [{
  json: {
    all_questions: mergedArray
  }
}];

